#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    // Usage check: need exactly two arguments (shift and text)
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    // The original binary only checks for argc < 3; extra arguments are ignored.
    // Parse shift argument (signed decimal), allowing leading '+' or '-'.
    char *endptr;
    long shift = strtol(argv[1], &endptr, 10);
    // Reduce shift modulo 26, handling negative values.
    int s = (int)(shift % 26);
    if (s < 0) s += 26;

    const char *input = argv[2];
    // Length limit of 1024 characters (same as original binary).
    if (strlen(input) > 1024) {
        puts("USAGE");
        return 0;
    }

    // Caesar cipher: rotate alphabetic characters, preserve case.
    for (size_t i = 0; input[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (c >= 'A' && c <= 'Z') {
            c = (c - 'A' + s) % 26 + 'A';
        } else if (c >= 'a' && c <= 'z') {
            c = (c - 'a' + s) % 26 + 'a';
        }
        putchar(c);
    }
    putchar('\n');
    return 0;
}
